from typing import List
import heapq

class Solution:
    def minimumCost(self, source: str, target: str, original: List[str], changed: List[str], cost: List[int]) -> int:
        # There are 26 lowercase English letters
        N = 26
        INF = 10**18

        # Initialize distance matrix with infinity
        # dist[i][j] = min cost to convert char i ('a'+i) to char j ('a'+j)
        dist = [[INF] * N for _ in range(N)]

        # Cost from a node to itself is 0
        for i in range(N):
            dist[i][i] = 0

        # Add direct edges from the transformation rules
        # Note: there might be multiple rules for the same (original, changed) pair.
        # We keep the minimum cost edge.
        for o_char, c_char, c in zip(original, changed, cost):
            u = ord(o_char) - ord('a')
            v = ord(c_char) - ord('a')
            if c < dist[u][v]:
                dist[u][v] = c

        # Floyd-Warshall algorithm to find all-pairs shortest paths
        # Complexity: O(26^3) which is very fast (~17k operations)
        for k in range(N):
            for i in range(N):
                # Optimization: if dist[i][k] is INF, no path exists via k
                if dist[i][k] == INF:
                    continue
                for j in range(N):
                    # Optimization: if dist[k][j] is INF, no path exists via k
                    if dist[k][j] == INF:
                        continue
                    if dist[i][j] > dist[i][k] + dist[k][j]:
                        dist[i][j] = dist[i][k] + dist[k][j]

        total_cost = 0
        for s_char, t_char in zip(source, target):
            if s_char == t_char:
                continue
            u = ord(s_char) - ord('a')
            v = ord(t_char) - ord('a')
            if dist[u][v] == INF:
                return -1
            total_cost += dist[u][v]

        return total_cost
